function removeVowels(s) {
  const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
  const kept = [];
  for (const ch of s) {
    if (!vowels.has(ch)) {
      kept.push(ch);
    }
  }
  return kept.join('');
}

