function generate(rand, size) {
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 10);
  const vowelShare = rand();
  const consonants = 'bcdfghjklmnpqrstvwxyz', vowels = 'aeiou';
  let s = '';
  for (let i = 0; i < n; i++) {
    const pool = rand() < vowelShare ? vowels : consonants;
    s += pool[Math.floor(rand() * pool.length)];
  }
  return [s];
}
